//! Deterministic content: every byte of a testkit file is a pure
//! function of `(seed, offset)`, so a test can check any range it
//! downloaded — or one it never even fetched — without the origin
//! holding the whole file in memory.

/// The byte at `offset` in the file generated by `seed`. A SplitMix64-style
/// bit mix: fast, and its dispersion means a bug that reads the wrong
/// offset (off-by-one, a transposed range) reliably produces a
/// *different* byte rather than accidentally matching by coincidence.
#[must_use]
pub fn content_byte(seed: u64, offset: u64) -> u8 {
    let mut x = seed ^ offset.wrapping_mul(0x9E37_79B9_7F4A_7C15);
    x = (x ^ (x >> 30)).wrapping_mul(0xBF58_476D_1CE4_E5B9);
    x = (x ^ (x >> 27)).wrapping_mul(0x94D0_49BB_1331_11EB);
    x ^= x >> 31;
    (x & 0xFF) as u8
}

/// `len` bytes of `seed`'s content starting at `start`.
#[must_use]
pub fn content_range(seed: u64, start: u64, len: u64) -> Vec<u8> {
    (start..start.saturating_add(len))
        .map(|offset| content_byte(seed, offset))
        .collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn is_deterministic() {
        assert_eq!(content_byte(1, 100), content_byte(1, 100));
    }

    #[test]
    fn different_seeds_usually_differ() {
        // Not a mathematical guarantee, just what makes this a useful
        // test fixture: two seeds should not produce identical files.
        let a = content_range(1, 0, 64);
        let b = content_range(2, 0, 64);
        assert_ne!(a, b);
    }

    #[test]
    fn different_offsets_usually_differ() {
        assert_ne!(content_byte(1, 0), content_byte(1, 1));
    }

    #[test]
    fn range_matches_individual_bytes() {
        let range = content_range(7, 10, 5);
        for (i, &byte) in range.iter().enumerate() {
            assert_eq!(byte, content_byte(7, 10 + i as u64));
        }
    }

    #[test]
    fn empty_range_is_empty() {
        assert_eq!(content_range(1, 0, 0), Vec::<u8>::new());
    }
}
